use nanbox::JsValue;

// Stub for `__esc_dispatch` which is normally generated by Cranelift/LLVM
// codegen in the final binary. During tests, this symbol must be provided to
// satisfy the `extern "C"` declaration in `runtime::rt_api`.
#[unsafe(no_mangle)]
extern "C" fn __esc_dispatch(_func_idx: i32, _argc: i32, _argv: *const u64) -> u64 {
    // Return NaN-boxed undefined
    0x7FF8_0004_0000_0000_u64
}

// === Helper functions ===

/// Helper to create a test string JsValue from a &str.
/// Layout mirrors `runtime::string_ops::RtString { data: String }`.
fn test_make_string(s: &str) -> JsValue {
    #[repr(C)]
    struct TestString {
        data: String,
    }
    let rt_str = Box::new(TestString {
        data: s.to_string(),
    });
    let raw_ptr = Box::into_raw(rt_str) as *const ();
    JsValue::string(raw_ptr)
}

/// Helper to extract string data from a JsValue for assertions.
fn test_extract_string(val: &JsValue) -> Option<String> {
    #[repr(C)]
    struct TestString {
        data: String,
    }
    if let Some(ptr) = val.as_string() {
        if ptr.is_null() {
            return Some(String::new());
        }
        let rt_str = unsafe { &*(ptr as *const TestString) };
        Some(rt_str.data.clone())
    } else {
        None
    }
}

/// Helper to create a TaggedObj<JsObject> for tests that need plain objects.
fn make_tagged_plain_object() -> u64 {
    runtime::rt_api::__esc_rt_create_object()
}

