#[test]
fn test_registry_new_empty() {
    let reg = crate::registry::BuiltinRegistry::new();
    assert!(reg.is_empty());
    assert_eq!(reg.len(), 0);
}

#[test]
fn test_registry_with_defaults() {
    let reg = crate::registry::BuiltinRegistry::with_defaults();
    assert!(!reg.is_empty());
    assert_eq!(reg.len(), 6);
    assert!(reg.contains("isNaN"));
    assert!(reg.contains("isFinite"));
    assert!(reg.contains("parseInt"));
    assert!(reg.contains("parseFloat"));
    assert!(reg.contains("encodeURIComponent"));
    assert!(reg.contains("decodeURIComponent"));
}

#[test]
fn test_registry_default_trait() {
    let reg = crate::registry::BuiltinRegistry::default();
    assert_eq!(reg.len(), 6);
}

#[test]
fn test_registry_lookup_exists() {
    let reg = crate::registry::BuiltinRegistry::with_defaults();
    let is_nan = reg.get("isNaN");
    assert!(is_nan.is_some());
}

#[test]
fn test_registry_lookup_missing() {
    let reg = crate::registry::BuiltinRegistry::with_defaults();
    assert!(reg.get("nonexistent").is_none());
    assert!(!reg.contains("nonexistent"));
}

#[test]
fn test_registry_register_custom() {
    let mut reg = crate::registry::BuiltinRegistry::new();
    fn my_fn(_args: &[JsValue]) -> JsValue {
        JsValue::int(42)
    }
    reg.register("myFunc", my_fn);
    assert!(reg.contains("myFunc"));
    assert_eq!(reg.len(), 1);

    let func = reg.get("myFunc").unwrap();
    let result = func(&[]);
    assert_eq!(result.as_int(), Some(42));
}

#[test]
fn test_registry_register_overwrite() {
    let mut reg = crate::registry::BuiltinRegistry::new();
    fn fn_a(_args: &[JsValue]) -> JsValue {
        JsValue::int(1)
    }
    fn fn_b(_args: &[JsValue]) -> JsValue {
        JsValue::int(2)
    }
    reg.register("f", fn_a);
    reg.register("f", fn_b);
    assert_eq!(reg.len(), 1);

    let func = reg.get("f").unwrap();
    let result = func(&[]);
    assert_eq!(result.as_int(), Some(2));
}

