#[test]
fn test_array_of() {
    let arr = crate::array::of(&[JsValue::int(1), JsValue::int(2), JsValue::int(3)]);
    assert!(arr.is_object());
    let len = crate::array::length(&[arr]);
    assert_eq!(len.as_int(), Some(3));
}

#[test]
fn test_array_push_pop() {
    let arr = crate::array::of(&[JsValue::int(1)]);
    crate::array::push(&[arr, JsValue::int(2), JsValue::int(3)]);
    assert_eq!(crate::array::length(&[arr]).as_int(), Some(3));

    let popped = crate::array::pop(&[arr]);
    assert_eq!(popped.as_int(), Some(3));
    assert_eq!(crate::array::length(&[arr]).as_int(), Some(2));
}

#[test]
fn test_array_pop_empty() {
    let arr = crate::array::of(&[]);
    let result = crate::array::pop(&[arr]);
    assert!(result.is_undefined());
}

#[test]
fn test_array_shift_unshift() {
    let arr = crate::array::of(&[JsValue::int(2), JsValue::int(3)]);

    // unshift adds to front
    crate::array::unshift(&[arr, JsValue::int(1)]);
    assert_eq!(crate::array::length(&[arr]).as_int(), Some(3));

    // shift removes from front
    let shifted = crate::array::shift(&[arr]);
    assert_eq!(shifted.as_int(), Some(1));
    assert_eq!(crate::array::length(&[arr]).as_int(), Some(2));
}

#[test]
fn test_array_shift_empty() {
    let arr = crate::array::of(&[]);
    let result = crate::array::shift(&[arr]);
    assert!(result.is_undefined());
}

