#[test]
fn test_promise_all_settled_mixed() {
    let p1 = crate::promise::resolve(&[JsValue::int(1)]);
    let p2 = crate::promise::reject(&[JsValue::int(2)]);
    let arr = make_promise_array(vec![p1, p2]);
    let result = crate::promise::all_settled(&[arr]);
    assert_eq!(
        crate::promise::get_state(&result),
        Some(crate::promise::PromiseState::Fulfilled)
    );
    let results = crate::promise::get_result_array(&result).unwrap();
    assert_eq!(results.len(), 2);

    // First entry should be fulfilled
    let (status1, val1) = crate::promise::get_settlement_entry(&results[0]).unwrap();
    assert!(status1.is_string());
    assert_eq!(val1.as_int(), Some(1));

    // Second entry should be rejected
    let (status2, val2) = crate::promise::get_settlement_entry(&results[1]).unwrap();
    assert!(status2.is_string());
    assert_eq!(val2.as_int(), Some(2));
}

