#[test]
fn test_aggregate_error_constructor() {
    let errors_array = crate::array::of(&[JsValue::int(1), JsValue::int(2)]);
    let msg = test_make_string("all failed");
    let agg = crate::error_types::aggregate_error(&[errors_array, msg]);
    assert!(agg.is_object());
    let kind = crate::error_types::get_aggregate_error_kind(&agg);
    assert_eq!(kind, Some(crate::error_types::JsErrorKind::AggregateError));
}

#[test]
fn test_aggregate_error_errors_property() {
    let errors_array = crate::array::of(&[JsValue::int(10), JsValue::int(20)]);
    let msg = test_make_string("multiple errors");
    let agg = crate::error_types::aggregate_error(&[errors_array, msg]);
    let errors = crate::error_types::get_aggregate_errors(&agg);
    assert!(errors.is_some());
    let errors_val = errors.unwrap();
    assert!(errors_val.is_object());
}

#[test]
fn test_aggregate_error_message_property() {
    let errors_array = crate::array::of(&[]);
    let msg = test_make_string("everything broke");
    let agg = crate::error_types::aggregate_error(&[errors_array, msg]);
    let msg_val = crate::error_types::get_aggregate_error_message(&agg);
    let extracted = test_extract_string(&msg_val);
    assert_eq!(extracted, Some("everything broke".to_string()));
}

#[test]
fn test_aggregate_error_is_error_subclass() {
    let errors_array = crate::array::of(&[]);
    let msg = test_make_string("test");
    let agg = crate::error_types::aggregate_error(&[errors_array, msg]);
    // AggregateError's kind name should be "AggregateError"
    let kind = crate::error_types::get_aggregate_error_kind(&agg);
    assert_eq!(kind, Some(crate::error_types::JsErrorKind::AggregateError));
    assert_eq!(
        crate::error_types::JsErrorKind::AggregateError.name(),
        "AggregateError"
    );
}

#[test]
fn test_aggregate_error_no_message() {
    let errors_array = crate::array::of(&[JsValue::int(1)]);
    let agg = crate::error_types::aggregate_error(&[errors_array]);
    let kind = crate::error_types::get_aggregate_error_kind(&agg);
    assert_eq!(kind, Some(crate::error_types::JsErrorKind::AggregateError));
    // Message should default to empty
    let msg_val = crate::error_types::get_aggregate_error_message(&agg);
    let extracted = test_extract_string(&msg_val);
    assert_eq!(extracted, Some(String::new()));
}

#[test]
fn test_aggregate_error_kind_name() {
    assert_eq!(
        crate::error_types::JsErrorKind::AggregateError.name(),
        "AggregateError"
    );
}

