// ========================================================================
// Symbol tests
// ========================================================================

#[test]
fn test_well_known_symbol_descriptions() {
    use crate::symbol::WellKnownSymbol;
    assert_eq!(WellKnownSymbol::Iterator.description(), "Symbol.iterator");
    assert_eq!(
        WellKnownSymbol::ToPrimitive.description(),
        "Symbol.toPrimitive"
    );
    assert_eq!(
        WellKnownSymbol::ToStringTag.description(),
        "Symbol.toStringTag"
    );
    assert_eq!(
        WellKnownSymbol::HasInstance.description(),
        "Symbol.hasInstance"
    );
    assert_eq!(
        WellKnownSymbol::IsConcatSpreadable.description(),
        "Symbol.isConcatSpreadable"
    );
    assert_eq!(WellKnownSymbol::Species.description(), "Symbol.species");
}

#[test]
fn test_well_known_symbol_equality() {
    use crate::symbol::WellKnownSymbol;
    assert_eq!(WellKnownSymbol::Iterator, WellKnownSymbol::Iterator);
    assert_ne!(WellKnownSymbol::Iterator, WellKnownSymbol::ToPrimitive);
}

#[test]
fn test_well_known_symbol_all() {
    use crate::symbol::WellKnownSymbol;
    let all = WellKnownSymbol::all();
    assert_eq!(all.len(), 6);
    assert!(all.contains(&WellKnownSymbol::Iterator));
    assert!(all.contains(&WellKnownSymbol::Species));
}

#[test]
fn test_well_known_symbol_debug() {
    use crate::symbol::WellKnownSymbol;
    let s = format!("{:?}", WellKnownSymbol::Iterator);
    assert_eq!(s, "Iterator");
}

#[test]
fn test_well_known_symbol_hash() {
    use crate::symbol::WellKnownSymbol;
    use std::collections::HashSet;
    let mut set = HashSet::new();
    set.insert(WellKnownSymbol::Iterator);
    set.insert(WellKnownSymbol::Iterator);
    set.insert(WellKnownSymbol::Species);
    assert_eq!(set.len(), 2);
}

