// ========================================================================
// process global object tests
// ========================================================================

#[test]
fn test_process_platform_is_non_empty() {
    let p = crate::process::platform();
    assert!(!p.is_empty(), "process.platform must be non-empty");
    // Must be one of the Node.js conventions
    assert!(
        ["linux", "darwin", "win32", "freebsd", "openbsd", "unknown"].contains(&p),
        "process.platform must use Node.js convention, got: {p}"
    );
}

#[test]
fn test_process_arch_is_non_empty() {
    let a = crate::process::arch();
    assert!(!a.is_empty(), "process.arch must be non-empty");
    // Must be one of the Node.js conventions
    assert!(
        ["x64", "arm64", "ia32", "arm", "unknown"].contains(&a),
        "process.arch must use Node.js convention, got: {a}"
    );
}

#[test]
fn test_process_version_starts_with_v() {
    let ver = crate::process::version();
    assert!(
        ver.starts_with('v'),
        "process.version must start with 'v', got: {ver}"
    );
    // Should contain a dot (semver)
    assert!(
        ver.contains('.'),
        "process.version must contain a dot, got: {ver}"
    );
}

#[test]
fn test_process_pid_is_positive() {
    let pid = crate::process::pid();
    assert!(
        pid > 0,
        "process.pid must be a positive integer, got: {pid}"
    );
}

#[test]
fn test_process_cwd_returns_non_empty() {
    let cwd = crate::process::cwd();
    assert!(
        !cwd.is_empty(),
        "process.cwd() must return a non-empty string"
    );
}

#[test]
fn test_process_argv_is_non_empty() {
    // In test context, host args_count returns the real process args
    let args = crate::process::argv();
    // The test runner itself should have at least 1 arg (the binary name)
    assert!(
        !args.is_empty(),
        "process.argv should have at least one element"
    );
}

#[test]
fn test_process_env_contains_path_or_home() {
    let env = crate::process::env_snapshot();
    let has_path = env.iter().any(|(k, _)| k == "PATH");
    let has_home = env.iter().any(|(k, _)| k == "HOME");
    assert!(
        has_path || has_home,
        "process.env should contain PATH or HOME"
    );
}

#[test]
fn test_process_env_snapshot_returns_pairs() {
    let env = crate::process::env_snapshot();
    assert!(
        !env.is_empty(),
        "process.env snapshot must contain at least one entry"
    );
    // Verify structure: each entry has non-empty key
    for (key, _val) in &env {
        assert!(
            !key.is_empty(),
            "environment variable key must not be empty"
        );
    }
}

#[test]
fn test_process_hrtime_returns_valid_pair() {
    let (seconds, nanoseconds) = crate::process::hrtime();
    // nanoseconds component must be < 1 billion
    assert!(
        nanoseconds < 1_000_000_000,
        "hrtime nanoseconds must be < 1e9, got: {nanoseconds}"
    );
    // seconds should be non-negative (monotonic clock)
    // seconds could be 0 right after boot, so we just check it's reasonable
    assert!(
        seconds > 0 || nanoseconds > 0,
        "hrtime must return a non-zero timestamp"
    );
}

#[test]
fn test_process_hrtime_is_monotonic() {
    let (s1, ns1) = crate::process::hrtime();
    // Do a small amount of work
    let _ = (0..1000).sum::<i32>();
    let (s2, ns2) = crate::process::hrtime();
    let total1 = s1 * 1_000_000_000 + ns1;
    let total2 = s2 * 1_000_000_000 + ns2;
    assert!(
        total2 >= total1,
        "hrtime must be monotonic: {total1} -> {total2}"
    );
}

#[test]
fn test_process_platform_matches_expected() {
    let p = crate::process::platform();
    // Verify we get the correct platform for the current system
    if cfg!(target_os = "linux") {
        assert_eq!(p, "linux");
    } else if cfg!(target_os = "macos") {
        assert_eq!(p, "darwin");
    } else if cfg!(target_os = "windows") {
        assert_eq!(p, "win32");
    }
}

#[test]
fn test_process_arch_matches_expected() {
    let a = crate::process::arch();
    // Verify we get the correct arch for the current system
    if cfg!(target_arch = "x86_64") {
        assert_eq!(a, "x64");
    } else if cfg!(target_arch = "aarch64") {
        assert_eq!(a, "arm64");
    }
}

